import React, { useState } from 'react';
import { QUESTIONS, PLATFORM_QUESTIONS } from '../utils/questions';

export default function Questionnaire({ onSubmit }) {

  // ✅ USER DATA (NO userId)
  const [userData, setUserData] = useState({
    age: "",
    gender: "",
    dailyScreenTime: "",
    sleepQuality: "",
    stressLevel: "",
    daysWithoutSocialMedia: "",
    exerciseFrequency: "",
    platform: "",
    happinessIndex: ""
  });

  const [answers, setAnswers] = useState({});
  const [platformUsage, setPlatformUsage] = useState({
    instagram: 0,
    youtube: 0,
    tiktok: 0,
    twitter: 0,
    facebook: 0,
    snapchat: 0,
  });

  const [selfRating, setSelfRating] = useState(5);
  const [current, setCurrent] = useState(0);
  const [phase, setPhase] = useState('userdata');

  const question = QUESTIONS?.[current];
  const totalQ = QUESTIONS.length;

  // ✅ SELECT ANSWER
  const selectAnswer = (qId, score) => {
    setAnswers((prev) => ({
      ...prev,
      [String(qId)]: score,
    }));
  };

  // ✅ NEXT QUESTION
  const nextQuestion = () => {
    if (!answers[String(question.id)]) return;

    if (current < totalQ - 1) {
      setCurrent(current + 1);
    } else {
      setPhase('platform');
    }
  };

  // ✅ BACK QUESTION
  const prevQuestion = () => {
    if (current > 0) setCurrent(current - 1);
  };

  // ✅ FINAL SUBMIT
 const handleSubmit = async () => {
  try {
    const res = await fetch('http://localhost:5000/api/responses', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        ...userData,
        answers,
        platformUsage,
        selfRating,
      }),
    });

    if (!res.ok) throw new Error('Server error');

    const result = await res.json();
    onSubmit(result); // ✅ success pe App.jsx ko batao

  } catch (err) {
    console.error('Submit failed:', err);
    alert('Failed to submit. Please try again.');
  }
};

  return (
    <div className="max-w-2xl mx-auto">

      {/* ================= USER DATA ================= */}
      {phase === 'userdata' && (
        <div className="card space-y-4">
          <h2 className="text-white text-xl mb-4">User Details</h2>

          <input className="input" placeholder="Age"
            onChange={(e)=>setUserData({...userData, age:e.target.value})} />

          <select className="input"
            onChange={(e)=>setUserData({...userData, gender:e.target.value})}>
            <option value="">Select Gender</option>
            <option>Male</option>
            <option>Female</option>
            <option>Other</option>
          </select>

          <input className="input" placeholder="Daily Screen Time (hrs)"
            onChange={(e)=>setUserData({...userData, dailyScreenTime:e.target.value})} />

          <input className="input" placeholder="Sleep Quality (1-10)"
            onChange={(e)=>setUserData({...userData, sleepQuality:e.target.value})} />

          <input className="input" placeholder="Stress Level (1-10)"
            onChange={(e)=>setUserData({...userData, stressLevel:e.target.value})} />

          <input className="input" placeholder="Days Without Social Media"
            onChange={(e)=>setUserData({...userData, daysWithoutSocialMedia:e.target.value})} />

          <input className="input" placeholder="Exercise Frequency (week)"
            onChange={(e)=>setUserData({...userData, exerciseFrequency:e.target.value})} />

          <select className="input"
            onChange={(e)=>setUserData({...userData, platform:e.target.value})}>
            <option value="">Select Platform</option>
            <option>Facebook</option>
            <option>Instagram</option>
            <option>YouTube</option>
            <option>LinkedIn</option>
            <option>X (Twitter)</option>
          </select>

          <input className="input" placeholder="Happiness Index (1-10)"
            onChange={(e)=>setUserData({...userData, happinessIndex:e.target.value})} />

          <button
            disabled={!userData.age || !userData.gender}
            onClick={()=>setPhase('questions')}
            className="btn-primary w-full"
          >
            Next
          </button>
        </div>
      )}

      {/* ================= QUESTIONS ================= */}
      {phase === 'questions' && question && (
        <div className="card">
          <h2 className="text-white text-xl mb-6">
            Q{current + 1}. {question.text}
          </h2>

          <div className="space-y-3">
            {question.options.map((opt, i) => {
              const selected = answers[String(question.id)] === opt.score;

              return (
                <button
                  key={i}
                  onClick={() => selectAnswer(question.id, opt.score)}
                  className={`w-full p-3 rounded ${
                    selected ? 'bg-blue-500 text-white' : 'bg-gray-700 text-white'
                  }`}
                >
                  {opt.label}
                </button>
              );
            })}
          </div>

          <div className="flex gap-3 mt-6">
            <button
              onClick={prevQuestion}
              disabled={current === 0}
              className="btn-secondary flex-1"
            >
              Back
            </button>

            <button
              onClick={nextQuestion}
              className="btn-primary flex-1"
            >
              Next
            </button>
          </div>
        </div>
      )}

      {/* ================= PLATFORM ================= */}
      {phase === 'platform' && (
        <div className="card">
          <h2 className="text-white text-xl mb-6">Platform Usage</h2>

          {PLATFORM_QUESTIONS.map((p) => (
            <div key={p.id} className="mb-3">
              <label className="text-white">{p.label}</label>
              <input
                type="range"
                min="0"
                max="10"
                value={platformUsage[p.id]}
                onChange={(e) =>
                  setPlatformUsage({
                    ...platformUsage,
                    [p.id]: Number(e.target.value),
                  })
                }
                className="w-full"
              />
            </div>
          ))}

          <button onClick={()=>setPhase('selfrating')} className="btn-primary w-full mt-4">
            Next
          </button>
        </div>
      )}

      {/* ================= SELF RATING ================= */}
      {phase === 'selfrating' && (
        <div className="card">
          <h2 className="text-white text-xl mb-4">Self Rating</h2>

          <input
            type="range"
            min="1"
            max="10"
            value={selfRating}
            onChange={(e)=>setSelfRating(Number(e.target.value))}
            className="w-full"
          />

          <p className="text-white text-center mt-2">{selfRating}/10</p>

          <button onClick={()=>setPhase('review')} className="btn-primary w-full mt-4">
            Next
          </button>
        </div>
      )}

      {/* ================= REVIEW ================= */}
      {phase === 'review' && (
        <div className="card">
          <h2 className="text-white text-xl mb-4">Final Step</h2>

          <button onClick={handleSubmit} className="btn-primary w-full">
            Submit Data
          </button>
        </div>
      )}

    </div>
  );
}
